package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.ObjectBuffer;
import com.fasterxml.jackson.databind.deser.std.StringArrayDeserializer;
import com.fasterxml.jackson.databind.deser.std.StringDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer__deserializeCustom_TriageGen1Test {

    private StringArrayDeserializer deserializer;
    private JsonParser jp;
    private DeserializationContext ctxt;
    private ObjectBuffer buffer;
    private StringDeserializer elementDeserializer;

    // A subclass to expose the protected method for testing
    private static class TestableStringArrayDeserializer extends StringArrayDeserializer {
        private final StringDeserializer customElementDeserializer;

        public TestableStringDeserializer(StringDeserializer customElementDeserializer) {
            this.customElementDeserializer = customElementDeserializer;
        }

        // We use reflection or a wrapper if we couldn't change the class, 
        // but since we are writing the test for a protected method, 
        // we assume the test class is in the same package or we use a subclass.
        @Override
        public String[] deserialize(JsonParser jp, DeserializationContext ctxt) throws IOException {
            return _deserializeCustom(jp, ctxt);
        }

        // To inject the _elementDeserializer which is private/protected in the real class
        // In a real scenario, we'd use reflection to set the _elementDeserializer field.
        public void setElementDeserializer(StringDeserializer deser) throws Exception {
            java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
            field.setAccessible(true);
            field.set(this, deser);
        }
    }

    @Before
    public void setUp() throws Exception {
        deserializer = new TestableStringArrayDeserializer(new StringDeserializer());
        jp = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        buffer = mock(ObjectBuffer.class);
        elementDeserializer = mock(StringDeserializer.class);

        // Inject the element deserializer via reflection
        java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
        field.setAccessible(true);
        field.set(deserializer, elementDeserializer);

        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);

        // Mock buffer behavior
        // We simulate a small buffer of size 2 to trigger the "ix >= chunk.length" branch
        Object[] initialChunk = new Object[2];
        when(buffer.resetAndStart()).thenReturn(initialChunk);
        when(buffer.appendCompletedChunk(any())).thenAnswer(invocation -> {
            Object[] oldChunk = invocation.getArgument(0);
            Object[] newChunk = new Object[oldChunk.length * 2];
            System.arraycopy(oldChunk, 0, newChunk, 0, oldChunk.length);
            return newChunk;
        });
        when(buffer.completeAndClearBuffer(any(), anyInt(), eq(String.class))).thenAnswer(invocation -> {
            Object[] chunk = invocation.getArgument(0);
            int count = invocation.getArgument(1);
            String[] result = new String[count];
            for (int i = 0; i < count; i++) {
                result[i] = (String) chunk[i];
            }
            return result;
        });
    }

    @Test
    public void testDeserializeEmptyArray() throws IOException {
        when(jp.nextToken()).thenReturn(JsonToken.END_ARRAY);

        String[] result = deserializer.deserialize(jp, ctxt);

        assertEquals(0, result.length);
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserializeSingleElement() throws IOException {
        when(jp.nextToken())
                .thenReturn(JsonToken.START_ARRAY)
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.END_ARRAY);

        when(elementDeserializer.deserialize(jp, ctxt)).thenReturn("hello");

        String[] result = deserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{"hello"}, result);
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserializeWithNull() throws IOException {
        when(jp.nextToken())
                .thenReturn(JsonToken.START_ARRAY)
                .thenReturn(JsonToken.VALUE_NULL)
                .thenReturn(JsonToken.END_ARRAY);

        String[] result = deserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{null}, result);
        verify(elementDeserializer, never()).deserialize(any(), any());
    }

    @Test
    public void testDeserializeWithBufferOverflow() throws IOException {
        // Initial buffer size is 2 (set in setUp)
        // We provide 3 elements to trigger: chunk = buffer.appendCompletedChunk(chunk);
        when(jp.nextToken())
                .thenReturn(JsonToken.START_ARRAY)
                .thenReturn(JsonToken.VALUE_STRING) // ix=0
                .thenReturn(JsonToken.VALUE_STRING) // ix=1
                .thenReturn(JsonToken.VALUE_STRING) // ix=2 -> triggers overflow
                .thenReturn(JsonToken.END_ARRAY);

        when(elementDeserializer.deserialize(eq(jp), eq(ctxt)))
                .thenReturn("a")
                .thenReturn("b")
                .thenReturn("c");

        String[] result = deserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{"a", "b", "c"}, result);
        verify(buffer, times(1)).appendCompletedChunk(any());
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test(expected = IOException.class)
    public void testDeserializeThrowsException() throws IOException {
        when(jp.nextToken()).thenReturn(JsonToken.START_ARRAY);
        when(elementDeserializer.deserialize(any(), any())).thenThrow(new IOException("Test Exception"));

        deserializer.deserialize(jp, ctxt);
    }
}
